var tokens = (Console.ReadLine() ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries);
if (tokens.Length != 4) Environment.Exit(1);
if (!long.TryParse(tokens[0], out var x1)) Environment.Exit(1);
if (!long.TryParse(tokens[1], out var y1)) Environment.Exit(1);
if (!long.TryParse(tokens[2], out var x2)) Environment.Exit(1);
if (!long.TryParse(tokens[3], out var y2)) Environment.Exit(1);
var sum = new Vector(x1, y1) + new Vector(x2, y2);
Console.WriteLine(sum.X + " " + sum.Y);

struct Vector
{
    public long X;
    public long Y;

    public Vector(long x, long y)
    {
        X = x;
        Y = y;
    }

    public static Vector operator +(Vector left, Vector right)
    {
        return new Vector(left.X + right.X, left.Y + right.Y);
    }
}
